WITH trades AS ( SELECT *, t_entry / 1e3 AS ts_entry, t_entry_s / 1e3 AS ts_entry_s
    FROM tc_trades_active ORDER BY alias_s, ticket_s, alias
), accounts_s AS ( SELECT alias AS acc_s, id AS id_s, owner AS owner_s,
    ${map_server:text}_s FROM tc_accounts WHERE (category = 0)
), accounts_t AS ( SELECT alias AS acc_t, id AS id_t, owner AS owner_t,
    ${map_server:text}_t FROM tc_accounts WHERE (category = 1)
), trades_s AS ( SELECT *, format('%s %s ("%s")', server_s, id_s, owner_s) AS acc_s2
    FROM trades INNER JOIN accounts_s ON trades.alias_s = accounts_s.acc_s
), trades_t AS ( SELECT *, format('%s %s ("%s")', server_t, id_t, owner_t) AS acc_t2
    FROM trades_s INNER JOIN accounts_t ON trades_s.alias = accounts_t.acc_t
)
SELECT * FROM trades_t

WITH trades AS ( SELECT (t_entry / 1e3) AS ts_entry, (t_exit_s / 1e3) AS ts_exit,
        (t_entry - t_entry_s) AS dt_entry, (t_exit - t_exit_s) AS dt_exit,
        (p_entry - p_entry_s) AS dp_entry, (p_exit - p_exit_s) AS dp_exit,
        alias_s, alias, ticket_s, ticket, symbol, order_type, lots, comment
    FROM tc_trades_closed WHERE $__unixEpochFilter(t_exit / 1e6)
    ORDER BY alias_s, ticket_s, alias
), accounts_s AS ( SELECT alias AS acc_s, id AS id_s, owner AS owner_s,
    ${map_server:text}_s FROM tc_accounts WHERE (category = 0)
), accounts_t AS ( SELECT alias AS acc_t, id AS id_t, owner AS owner_t,
    ${map_server:text}_t FROM tc_accounts WHERE (category = 1)
), trades_s AS ( SELECT *, format('%s %s ("%s")', server_s, id_s, owner_s) AS acc_s2
    FROM trades INNER JOIN accounts_s ON trades.alias_s = accounts_s.acc_s
), trades_t AS ( SELECT *, format('%s %s ("%s")', server_t, id_t, owner_t) AS acc_t2
    FROM trades_s INNER JOIN accounts_t ON trades_s.alias = accounts_t.acc_t
)
SELECT * FROM trades_t

WITH ordmap AS (
    SELECT CAST(ROUND(t_entry_s / 1e6) AS INT) as t_ord, EXTRACT(EPOCH FROM CURRENT_TIMESTAMP)
    AS t_now, alias_s, ticket_s, alias, ticket FROM tc_trades_active ORDER BY t_entry_s, alias
), accounts_s AS ( SELECT alias AS alias_s, owner AS owner_s, id AS id_s
    FROM tc_accounts WHERE (active = true) AND (category = 0)
), accounts_t AS ( SELECT alias AS alias_t, owner AS owner_t, id AS id_t
    FROM tc_accounts WHERE (active = true) AND (category = 1)
), ordmap_s AS ( SELECT * FROM ordmap LEFT JOIN accounts_s
    ON ordmap.alias_s = accounts_s.alias_s
), ordmap_t AS ( SELECT * FROM ordmap_s LEFT JOIN accounts_t
    ON ordmap_s.alias = accounts_t.alias_t
)
SELECT format('{"_t": %s, "_s": "A#%s - T#%s"}', t_now - t_ord, id_s, ticket_s) AS source,
    id_t AS target, ticket AS ticket FROM ordmap_t ORDER BY id_t, t_ord

/* CREATE OR REPLACE FUNCTION remove1() RETURNS text AS
$$ BEGIN RETURN 'Source :: |Target :: |\(.*\)'; END;
$$ LANGUAGE plpgsql; */

WITH timeseries AS ( SELECT DISTINCT ON (alias)
        alias, balance AS series FROM tc_timeseries
        ORDER BY alias, timestamp DESC
), accounts AS ( SELECT alias, id, owner,
        ${map_category:text}, ${map_server:text}
    FROM tc_accounts WHERE (active = true)
), merged AS ( SELECT series, ${map_metric:text}
    FROM timeseries INNER JOIN accounts
    ON timeseries.alias = accounts.alias
), parsed AS (
    SELECT series, regexp_replace(metric, remove1(), '', 'g') AS metric FROM merged
)
    SELECT series, regexp_replace(metric, ' :: ', ' ', 'g') AS metric FROM parsed

WITH timeseries AS ( SELECT balance AS series,
        (timestamp / 1e6) as time, alias FROM tc_timeseries
    WHERE $__unixEpochFilter(timestamp / 1e6)
), accounts AS ( SELECT alias, id, owner,
        ${map_category:text}, ${map_server:text}
    FROM tc_accounts WHERE (active = true)
), merged AS ( SELECT series,
        ${map_metric:text}, time
    FROM timeseries INNER JOIN accounts
    ON timeseries.alias = accounts.alias
    ORDER BY time
)
SELECT time, metric, series - FIRST_VALUE(series) OVER (PARTITION BY metric ORDER BY time) FROM merged ORDER BY time

WITH timeseries AS ( SELECT equity AS series,
        (timestamp / 1e6) as time, alias FROM tc_timeseries
    WHERE $__unixEpochFilter(timestamp / 1e6)
), accounts AS ( SELECT alias, id, owner,
        ${map_category:text}, ${map_server:text}
    FROM tc_accounts WHERE (active = true)
), merged AS ( SELECT series,
        ${map_metric:text}, time
    FROM timeseries INNER JOIN accounts
    ON timeseries.alias = accounts.alias
    ORDER BY time
)
SELECT time, metric, series - FIRST_VALUE(series) OVER (PARTITION BY metric ORDER BY time) FROM merged ORDER BY time

WITH timeseries AS ( SELECT lots_net AS series,
        (timestamp / 1e6) as time, alias FROM tc_timeseries
    WHERE $__unixEpochFilter(timestamp / 1e6)
), accounts AS ( SELECT alias, id, owner, max_lots_net,
        ${map_category:text}, ${map_server:text}
    FROM tc_accounts WHERE (active = true)
), merged AS ( SELECT series / max_lots_net AS series,
        ${map_metric:text}, time
    FROM timeseries INNER JOIN accounts
    ON timeseries.alias = accounts.alias
    ORDER BY time
)
SELECT * FROM merged

